\u002b\u0023\u0076\u0073\u0062\u0079\u006f\u0041\u0023\u006e\u0039\u0077\u005f\u004c\u0040\u004c\u0034\u0056\u003b\u007d\u0069\u005e\u004c\u0046\u0061\u0046\u0044\u0050\u003a\u002e\u002a\u005f\u004f\u002e\u0077\u0050\u0055\u0045\u007c\u0067\u006e\u006f\u0068\u0030\u0030\u0037\u0023\u0064\u002e\u002e\u0073\u006c\u0046\u0054\u0068\u0023\u0037\u006a\u007e\u007d\u0062\u0047\u0057\u0055\u0049\u004b\u007b\u0079\u004c\u004b\u005d\u0046\u0075\u0059\u0054\u0055\u002f\u0066\u0055\u0069\u004a\u0041\u0068\u0025\u0039\u0077\u002b\u0065\u003f\u0048\u003d\u0059\u003c\u004d\u0043\u0053\u0033\u0060\u007c\u0075\u0071\u0059\u0054\u0055\u0059\u007a\u0069\u0073\u0047\u0024\u007e\u0078\u0038\u004f\u005e\u0043\u0074\u007d\u0055\u0049\u004b\u006a\u0079\u0029\u0034\u005b\u004f\u0023\u0031\u0045\u004f\u003a\u0044\u002e\u0030\u004e\u0035\u0060\u0047\u0073\u0036\u002c\u004e\u004a\u0045\u007b\u006c\u0058\u0037\u0030\u0044\u006a\u0052\u006d\u0022\u005b\u0041\u0023\u0076\u007b\u0038\u006b\u0074\u0045\u0022\u0046\u005e\u0026\u0069\u0047\u0056\u0036\u0043\u006a\u006b\u006d\u003c\u0076\u0029\u006c\u007d\u0037\u0025\u004e\u0036\u0045\u0058\u003a\u0038\u0062\u006d\u0041\u0041\u002a\u0074\u0062\u0048\u005d\u0068\u007b\u003f\u002f\u0022\u004c\u0070\u003c\u0050\u0067\u0078\u0050\u0076\u0045\u0037\u005a\u0032\u003d\u005b\u002a\u004e\u0055\u0046\u0070\u0052\u0038\u0069\u0066\u0033\u0066\u0056\u007d\u005d\u002c\u007d\u0065\u005e\u0059\u0047\u0063\u0077\u0030\u005d\u003f\u0079\u0077\u0050\u0035\u004a\u0030\u0049\u0074\u0037\u0053\u0073\u0076\u007a\u0065\u004e\u004d\u007d\u002b\u0049\u0069\u007e\u0035\u004a\u007e\u0042\u0059\u0047\u0058\u0051\u0029\u005a\u002c\u0070\u003c\u0050\u0033\u0057\u0024\u0023\u0032\u003c\u002c\u007c\u0030\u005a\u005f\u005d\u004c\u0066\u006c\u0064\u003b\u0057\u0031\u005f\u0039\u006f\u0053\u0073\u0029\u002e\u006f\u005d\u0038\u0042\u006f\u0032\u004b\u007c\u006a\u003c\u0033\u0063\u0071\u0044\u0051\u0028\u0041\u005d\u002f\u002f\u0026\u0046\u0070\u0056\u0049\u005d\u004e\u0037\u002c\u0033\u003d\u0073\u0060\u007d\u004e\u0074\u0064\u0072\u0045\u007e\u0048\u004c\u0074\u0037\u0071\u0044\u0061\u005b\u006d\u005d\u003f\u0070\u0057\u0046\u0072\u0073\u0063\u0076\u003c\u004d\u0055\u007b\u0039\u0059\u003f\u003d\u0072\u005a\u006c\u0024\u0046\u007e\u006e\u0036\u0046\u0041\u0069\u007b\u0056\u005b\u0075\u003e\u002a\u0042\u006e\u0054\u0021\u0056\u0039\u0072\u0025\u0030\u0029\u0048\u0031\u0059\u005e\u0065\u004b\u0066\u0071\u0049\u0032\u0025\u007e\u0023\u0028\u0030\u0051\u004b\u0054\u0079\u0069\u0079\u0073\u0050\u0054\u007e\u0068\u0072\u0066\u0046\u0042\u002a\u003d\u007a\u004f\u002f\u007a\u0063\u0057\u004e\u0038\u0026\u0077\u0058\u0079\u0025\u005e\u004e\u0071\u003c\u002a\u0051\u0073\u0055\u0060\u0060\u0026\u0032\u0061\u003c\u006f\u0022\u0046\u002a\u004b\u0055\u005d\u0055\u006d\u004e\u0056\u005b\u002e\u0029\u0038\u0037\u005d\u0058\u0074\u0023\u0062\u0051\u0065\u0054\u007b\u002e\u0043\u0036\u0069\u0025\u0075\u002f\u006b\u0070\u0051\u0045\u0062\u0032\u0076\u0075\u0069\u0031\u0049\u0068\u0053\u0042\u0050\u0056\u0052\u005b\u0057\u0061\u0041\u0051\u0067\u007a\u0063\u005b\u0074\u0057\u005b\u002e\u0029\u0038\u0037\u0033\u007e\u0059\u007a\u002a\u0030\u0028\u007c\u0022\u004e\u0038\u0026\u0077\u0058\u006d\u006b\u0071\u0049\u0057\u0062\u0022\u0078\u007c\u0051\u0051\u0063\u002e\u0031\u005e\u004a\u0040\u0025\u005f\u0030\u003b\u0064\u007e\u005f\u0071\u0078\u0029\u002f\u0055\u007e\u0053\u007a\u005f\u0046\u004c\u007b\u0025\u0042\u003b\u0066\u005e\u0028\u0076\u0075\u004d\u0046\u0069\u002c\u0076\u0059\u002a\u002f\u0050\u0029\u006b\u0021\u005e\u007d\u0041\u0069\u0022\u0036\u0023\u0040\u0040\u003f\u0036\u003b\u0026\u0026\u004a\u0047\u0068\u0065\u0069\u0036\u003f\u0074\u0040\u003a\u005d\u0062\u002b\u0040\u0040\u003f\u0036\u003b\u0026\u0026\u004a\u0047\u0068\u0065\u0069\u0043\u0030\u0057\u002a\u0054\u0078\u003a\u003a\u0063\u004b\u004c\u0053\u0041\u005d\u0045\u0037\u004b\u0055\u0030\u006d\u0026\u003d\u0043\u0078\u0052\u0038\u0065\u006b\u0042\u004b\u0064\u0062\u0030\u006e\u005d\u0055\u006d\u004e\u0026\u0047\u0052\u0038\u0037\u004f\u0063\u0034\u0024\u005f\u0048\u005d\u0062\u003b\u006c\u003b\u0037\u0043\u0071\u0025\u004f\u0050\u0067\u0063\u0077\u0062\u006a\u0058\u0076\u006a\u006e\u006e\u0066\u0032\u004e\u005a\u006f\u0067\u0041\u004b\u0038\u0031\u0032\u0066\u003c\u0026\u0021\u0033\u0044\u006c\u003b\u0070\u007c\u0022\u003f\u005e\u007b\u0030\u0043\u0031\u006c\u0079\u002f\u0057\u0076\u0071\u0074\u003c\u005f\u0077\u004d\u005b\u0074\u003d\u003f\u006b\u005f\u0072\u002e\u002e\u002e\u0075\u003c\u0046\u006e\u0069\u002b\u0062\u006f\u0041\u004e\u0067\u0041\u003b\u006c\u0065\u0074\u005f\u0033\u006b\u0076\u0047\u0042\u005a\u0063\u0023\u0031\u007a\u0036\u007e\u0038\u0058\u0074\u0047\u0062\u0051\u0065\u0054\u007b\u0031\u0049\u004d\u0060\u0062\u0058\u0022\u006b\u003c\u0032\u0055\u0073\u004b\u0021\u0063\u0041\u007d\u0049\u0058\u0069\u0035\u0058\u0075\u0038\u003d\u0023\u0039\u0021\u007e\u0062\u0057\u0042\u003d\u004a\u0045\u002e\u0068\u007d\u002f\u006b\u0060\u0031\u0076\u007a\u0040\u0076\u006a\u0038\u0037\u004e\u0068\u0053\u0062\u007e\u0047\u006b\u0073\u0025\u0057\u0062\u0022\u0078\u0025\u007b\u002e\u006f\u0057\u0053\u0066\u007d\u0041\u0025\u004e\u006b\u0044\u0038\u0044\u0038\u0063\u0072\u0053\u0066\u0026\u0023\u0045\u0038\u0074\u002e\u0025\u0024\u005d\u0059\u0031\u0066\u0022\u0026\u002c\u0045\u0048\u003f\u0035\u0062\u0046\u0049\u0076\u0053\u0065\u004f\u0044\u0037\u006c\u0051\u0034\u003f\u0064\u0039\u0070\u004c\u0024\u0071\u0057\u0054\u003f\u004f\u0052\u0029\u0042\u0077\u0075\u003f\u0024\u0046\u0051\u002f\u005f\u0062\u0051\u0046\u0051\u0060\u0042\u004f\u007d\u0037\u0077\u0068\u0024\u0035\u005d\u0078\u006a\u0021\u0062\u0055\u0073\u0049\u0067\u0025\u007d\u006b\u0074\u0022\u0037\u0054\u0069\u0026\u002b\u004d\u007d\u0067\u004e\u0045\u0057\u003e\u005b\u003f\u0055\u007d\u0073\u0074\u0067\u002e\u0022\u0052\u003a\u002b\u0045\u0066\u0037\u0039\u0034\u0063\u002f\u007d\u006d\u004a\u0071\u0048\u002b\u0052\u0068\u0054\u0041\u002a\u003e\u003f\u005a\u005b\u006d\u0022\u006e\u0040\u003d\u0021\u0057\u003f\u0073\u0066\u0048\u0057\u0067\u006f\u0032\u0058\u0074\u0075\u0028\u0022\u0040\u0040\u0021\u0076\u004d\u005b\u005b\u0026\u004f\u0057\u0046\u0055\u0076\u0021\u0073\u004f\u002f\u003e\u0051\u002b\u0073\u0042\u006c\u0040\u0071\u003d\u0030\u0066\u0058\u0073\u002a\u0061\u0071\u0051\u0063\u005e\u0051\u003c\u0041\u0021\u0064\u005b\u0057\u002b\u007a\u0032\u0065\u0045\u0061\u0074\u003e\u0059\u0037\u0049\u0056\u0049\u007c\u0038\u0062\u0046\u005a\u005e\u0037\u0043\u0037\u002f\u0054\u006b\u004c\u007e\u0075\u0064\u002b\u006d\u004a\u004c\u0074\u007a\u0055\u0043\u0033\u006d\u003f\u003d\u006c\u0025\u005e\u0037\u0036\u005e\u0065\u003d\u0045\u0065\u0045\u0069\u002e\u006f\u005f\u0074\u0058\u0075\u0048\u0068\u0071\u002c\u006f\u0044\u002e\u0032\u0067\u0035\u0031\u0062\u0032\u0069\u002c\u006a\u002a\u0064\u0077\u0070\u0041\u0062\u004e\u0047\u003a\u006a\u0070\u0025\u0023\u004c\u0074\u0025\u0046\u0077\u0063\u005d\u0022\u006d\u0045\u005f\u004c\u0074\u006f\u004c\u002f\u0036\u0049\u0051\u003f\u007e\u0064\u007b\u0074\u0034\u0062\u004c\u0069\u0057\u003c\u003a\u0047\u0048\u006b\u0022\u0076\u0053\u006c\u0076\u0022\u0056\u005e\u007b\u0033\u003a\u004d\u003a\u0047\u0035\u0039\u0057\u002b\u0046\u004f\u002a\u0022\u006a\u004c\u007b\u0033\u003a\u004d\u0021\u0023\u0059\u0070\u003e\u003f\u0058\u0068\u0037\u0037\u0023\u0074\u0030\u0069\u006f\u003c\u006e\u0021\u0025\u007b\u0052\u004f\u0034\u006f\u0037\u0037\u0078\u004e\u0035\u0065\u0071\u004d\u0061\u0071\u0051\u0061\u003a\u003c\u0069\u005d\u006d\u0028\u003a\u006b\u006a\u0072\u006d\u0059\u007e\u003b\u0051\u0062\u0056\u0077\u0043\u0048\u004d\u002b\u005e\u003e\u0050\u005f\u0052\u0064\u0051\u004e\u0031\u003e\u006b\u005a\u0025\u004e\u0023\u006f\u004f\u002c\u0073\u0058\u0036\u0064\u0078\u0065\u0022\u0068\u0066\u004e\u006f\u004f\u004c\u004c\u005b\u0066\u005f\u004d\u004d\u0032\u0035\u0038\u002a\u005a\u002f\u003c\u0075\u006f\u0063\u002b\u0040\u0053\u003b\u006f\u005b\u0072\u006c\u0047\u0057\u0065\u0079\u0057\u003e\u005d\u0051\u007d\u0054\u0022\u006e\u002a\u003c\u0044\u003f\u0070\u006c\u002f\u003f\u0055\u006e\u0074\u0072\u003d\u0042\u0030\u0049\u0064\u002b\u0055\u0030\u0055\u002e\u0051\u0054\u0024\u002a\u006e\u006e\u004d\u005a\u005b\u002f\u0049\u0067\u0071\u0030\u0022\u003e\u0064\u0024\u0066\u0029\u003a\u0074\u0031\u007d\u0022\u007b\u006d\u0057\u0057\u007c\u0036\u0055\u0058\u0037\u0032\u0075\u0067\u007e\u0030\u0036\u0055\u006b\u0034\u003c\u006c\u0047\u0057\u006c\u003a\u003e\u0030\u0066\u0040\u0030\u0043\u0055\u0053\u0029\u0057\u0067\u006f\u0021\u0058\u006b\u004d\u0078\u0067\u003f\u0029\u003f\u004f\u0039\u0031\u0058\u0070\u0031\u006e\u005a\u0046\u0038\u0029\u0054\u004a\u0079\u0049\u0037\u0031\u0048\u004f\u004b\u006a\u0030\u003f\u007c\u0042\u0069\u007b\u003a\u0031\u007b\u003e\u0064\u004f\u0030\u0071\u0034\u003f\u002a\u006e\u0036\u003d\u0037\u005f\u006b\u0079\u0035\u0048\u0033\u003e\u0066\u007e\u0061\u005e\u0026\u0043\u0060\u0021\u006a\u0021\u0064\u004f\u004b\u0063\u0028\u0068\u002f\u0052\u0047\u002c\u0033\u0039\u0045\u0062\u0075\u0066\u006f\u0076\u0075\u0056\u002b\u006b\u0043\u0072\u0068\u0045\u0069\u005b\u0023\u0066\u0072\u0063\u0055\u0054\u004f\u0043\u0056\u0070\u0040\u007a\u0064\u0072\u006a\u0073\u0070\u0025\u0022\u003e\u005e\u004f\u0039\u0031\u004f\u003c\u006e\u0068\u0024\u007d\u004b\u007b\u0070\u0078\u007b\u0030\u0060\u007a\u0031\u0043\u0064\u0065\u0035\u0041\u0054\u0079\u003b\u0038\u006e\u003f\u003c\u0023\u0051\u0068\u0066\u0052\u0041\u0058\u0074\u0068\u0056\u0037\u002b\u005e\u0034\u0030\u0045\u0023\u0050\u0073\u003a\u0049\u0061\u0061\u007d\u007e\u003f\u0049\u0049\u0025\u0039\u0042\u007c\u0058\u0031\u0059\u007b\u0037\u0060\u0057\u0070\u006a\u0058\u0074\u0076\u0042\u0068\u0040\u0033\u0055\u0030\u0044\u0065\u0041\u002e\u0075\u003d\u0060\u0023\u005e\u0026\u0043\u0060\u0021\u006a\u0043\u005b\u0032\u0021\u0065\u0076\u0036\u003d\u0046\u0068\u0049\u002a\u0066\u0026\u0050\u0073\u0043\u0064\u0066\u005b\u0064\u005f\u0028\u0064\u0037\u0059\u0037\u0062\u004a\u0051\u0062\u003a\u0068\u0030\u007c\u0046\u0029\u0034\u0050\u0024\u003f\u0033\u0069\u0045\u0031\u0052\u004a\u003e\u0066\u007e\u0035\u003c\u0052\u0052\u0069\u0063\u0032\u002a\u0037\u0062\u007a\u007c\u006d\u003a\u003d\u0038\u005f\u0076\u0042\u0046\u0047\u0060\u007d\u0074\u0060\u0066\u003c\u0035\u007e\u0060\u006a\u005a\u0039\u0066\u0074\u0043\u0032\u005b\u005b\u005b\u0047\u0048\u0064\u003a\u004d\u0021\u0037\u007b\u0042\u0046\u005d\u0042\u0067\u0053\u0078\u007d\u0043\u0056\u0050\u0059\u006e\u0068\u0039\u0061\u0030\u0075\u002f\u0071\u002c\u0033\u0037\u0026\u002a\u0048\u0074\u0051\u0037\u004c\u0070\u0039\u0075\u0034\u0077\u0071\u005e\u0026\u0034\u0024\u006b\u0043\u007b\u0043\u0045\u006a\u007c\u0056\u0043\u0038\u004e\u0031\u007e\u006b\u0072\u007c\u0031\u004e\u004c\u0022\u0023\u0059\u0045\u0072\u0050\u0037\u0026\u002e\u0072\u0045\u0040\u0038\u002a\u0072\u002c\u0076\u0063\u0077\u0044\u0044\u0023\u007e\u005e\u0073\u0073\u0072\u002e\u004e\u0051\u004a\u007e\u0023\u0070\u002a\u003b\u0038\u0062\u005e\u0048\u005d\u0039\u0054\u004f\u0066\u0037\u004a\u0022\u0054\u0077\u002b\u0024\u0074\u0065\u0045\u0057\u005d\u003a\u0045\u003c\u0022\u004b\u0028\u0044\u0044\u0023\u007e\u005e\u0073\u0073\u0072\u002e\u004e\u0051\u004a\u0079\u0041\u0071\u002b\u0047\u003c\u006a\u0075\u005d\u0037\u003b\u0025\u005b\u0079\u0068\u007e\u0079\u0050\u006d\u0040\u0034\u0074\u0052\u0055\u007a\u0031\u003d\u007a\u002c\u0064\u0025\u0051\u0044\u0033\u0070\u003f\u0036\u0054\u006b\u0031\u006d\u0062\u0075\u0058\u0031\u004e\u0043\u0033\u0047\u006c\u007e\u005b\u0021\u0045\u0070\u0056\u0067\u0028\u0053\u005a\u0056\u0079\u002f\u003f\u0067\u0077\u0037\u0040\u002c\u0057\u0078\u003d\u004e\u0068\u0030\u0079\u004c\u0077\u004c\u0071\u0031\u0036\u0065\u0070\u004b\u0047\u005a\u0025\u006b\u0039\u0031\u004d\u007e\u0034\u0032\u0036\u0058\u0077\u0065\u0068\u005f\u0029\u0049\u007e\u005e\u007c\u003d\u003f\u002e\u0066\u004b\u0039\u0079\u0039\u0070\u0076\u0024\u0024\u0057\u0070\u005d\u007a\u0028\u0055\u004c\u0050\u0044\u006f\u0060\u0053\u0076\u0041\u002c\u0033\u0061\u006d\u004a\u0047\u0055\u0023\u007e\u0034